describe('Table Row Selection with Header Checkbox', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should select all rows using the header checkbox', () => {
    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Verify header checkbox exists and is unchecked
    cy.get('[data-testid="header-checkbox"]').should('be.visible').should('not. be checked');

    // Verify row checkboxes exist and are unchecked
    cy.get('[data-testid="row-checkbox"]').first().should('be.visible').should('not. be checked');

    // Click header checkbox to select all rows
    cy.get('[data-testid="header-checkbox"]').click();

    // Verify header checkbox is now checked
    cy.get('[data-testid="header-checkbox"]').should('be. checked');

    // Verify all row checkboxes are now checked
    cy.get('[data-testid="row-checkbox"]').each(($rowCheckbox) => {
      cy.wrap($rowCheckbox).should('be. checked');
    });

    // Verify selection count is updated
    cy.get('[data-testid="selected-row-count"]').should('contain', 'All');

    // Verify action button is enabled
    cy.get('[data-testid="export-button"]').should('not. be disabled');
  });

  it('should unselect all rows when header checkbox is unchecked', () => {
    // Select all rows first
    cy.get('[data-testid="header-checkbox"]').click();
    cy.get('[data-testid="row-checkbox"]').first().should('be. checked');

    // Verify selection count is updated
    cy.get('[data-testid="selected-row-count"]').should('contain', 'All');

    // Uncheck header checkbox
    cy.get('[data-testid="header-checkbox"]').click();

    // Verify header checkbox is now unchecked
    cy.get('[data-testid="header-checkbox"]').should('not. be checked');

    // Verify all row checkboxes are now unchecked
    cy.get('[data-testid="row-checkbox"]').each(($rowCheckbox) => {
      cy.wrap($rowCheckbox).should('not. be checked');
    });

    // Verify selection count is reset
    cy.get('[data-testid="selected-row-count"]').should('contain', '0');

    // Verify action button is disabled
    cy.get('[data-testid="export-button"]').should('be. disabled');
  });
});
